def minimum_cost(nums: list[int]) -> int:
    first = second = float("inf")   # two smallest values after index 0
    for x in nums[1:]:
        if x < first:
            first, second = x, first
        elif x < second:
            second = x
    return nums[0] + first + second

def distribute_candies(n: int, limit: int) -> int:
    def free_ways(m: int) -> int:
        # ways to split m candies among 3 children with no limit
        return (m + 2) * (m + 1) // 2 if m >= 0 else 0

    over = limit + 1   # forcing one child above the limit uses this many
    return (free_ways(n)
            - 3 * free_ways(n - over)
            + 3 * free_ways(n - 2 * over)
            - free_ways(n - 3 * over))

def is_zero_array(nums: list[int], queries: list[list[int]]) -> bool:
    n = len(nums)
    diff = [0] * (n + 1)
    for l, r in queries:
        diff[l] += 1
        diff[r + 1] -= 1
    cover = 0
    for j in range(n):
        cover += diff[j]          # number of queries that include index j
        if cover < nums[j]:
            return False
    return True

def clear_stars(s: str) -> str:
    where = [[] for _ in range(26)]   # surviving indices of each letter
    removed = [False] * len(s)
    for i, ch in enumerate(s):
        if ch != "*":
            where[ord(ch) - 97].append(i)
            continue
        removed[i] = True
        for stack in where:           # smallest letter that is still present
            if stack:
                removed[stack.pop()] = True   # its rightmost copy
                break
    return "".join(ch for i, ch in enumerate(s) if not removed[i])

