def max_number_of_families(n: int, reserved_seats: list[list[int]]) -> int:
    taken = defaultdict(int)          # row -> bitmask of reserved seats
    for row, seat in reserved_seats:
        taken[row] |= 1 << seat
    left = sum(1 << s for s in range(2, 6))     # seats 2..5
    middle = sum(1 << s for s in range(4, 8))   # seats 4..7
    right = sum(1 << s for s in range(6, 10))   # seats 6..9
    families = 2 * (n - len(taken))   # untouched rows hold two families
    for mask in taken.values():
        if not mask & left and not mask & right:
            families += 2
        elif not mask & left or not mask & middle or not mask & right:
            families += 1
    return families

