def build_tree(inorder: list[int], postorder: list[int]) -> Optional[TreeNode]:
    if not postorder:
        return None
    root = TreeNode(postorder[-1])
    stack = [root]            # nodes whose left subtree is not built yet
    i = len(inorder) - 1      # walks inorder from the right end
    for value in reversed(postorder[:-1]):
        node = TreeNode(value)
        parent = None
        # a node equal to inorder[i] has its right subtree finished
        while stack and stack[-1].val == inorder[i]:
            parent = stack.pop()
            i -= 1
        if parent is not None:
            parent.left = node
        else:
            stack[-1].right = node
        stack.append(node)
    return root

