def paint_walls(cost: list[int], time: list[int]) -> int:
    n = len(cost)
    INF = float("inf")
    dp = [0] + [INF] * n     # dp[j]: least cost to account for at least j walls
    for c, t in zip(cost, time):
        # paying for this wall covers itself plus t walls for the free painter
        for j in range(n, 0, -1):
            prev = dp[max(0, j - t - 1)]
            if prev + c < dp[j]:
                dp[j] = prev + c
    return dp[n]

