def generate_string(str1: str, str2: str) -> str:
    n, m = len(str1), len(str2)
    length = n + m - 1

    # Z function of str2: z[d] = longest common prefix of str2 and str2[d:].
    z = [0] * m
    z[0] = m
    left = right = 0
    for d in range(1, m):
        if d < right:
            z[d] = min(right - d, z[d - left])
        while d + z[d] < m and str2[z[d]] == str2[d + z[d]]:
            z[d] += 1
        if d + z[d] > right:
            left, right = d, d + z[d]

    word = ["a"] * length
    fixed = [False] * length
    prev_t = -1
    for i in range(n):
        if str1[i] != "T":
            continue
        if prev_t >= 0 and i - prev_t < m:
            shift = i - prev_t
            if z[shift] < m - shift:   # overlapping T windows disagree
                return ""
        # Write only the positions not already covered by the previous T window.
        start = max(i, prev_t + m) if prev_t >= 0 else i
        for p in range(start, i + m):
            word[p] = str2[p - i]
            fixed[p] = True
        prev_t = i

    # last_free[p] = largest free index <= p, or -1.
    last_free = [-1] * length
    latest = -1
    for p in range(length):
        if not fixed[p]:
            latest = p
        last_free[p] = latest

    target = list(str2)
    for i in range(n):
        if str1[i] == "F" and word[i:i + m] == target:
            j = last_free[i + m - 1]
            if j < i:          # every letter in this window is forced
                return ""
            word[j] = "b"      # smallest possible damage to the order
    return "".join(word)

