    # Prefix function (failure links) of the pattern.
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and pattern[i] != pattern[k]:
            k = fail[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        fail[i] = k

    count = 0
    k = 0  # length of the current partial match
    for j in range(len(nums) - 1):
        a, b = nums[j], nums[j + 1]
        sign = 1 if b > a else (0 if b == a else -1)
        while k and sign != pattern[k]:
            k = fail[k - 1]
        if sign == pattern[k]:
            k += 1
        if k == m:
            count += 1
            k = fail[k - 1]  # allow overlapping matches
    return count

