def _occurrences(text: str, pat: str) -> list[int]:
    """All start indices of pat in text using KMP."""
    m = len(pat)
    if m > len(text):
        return []
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and pat[i] != pat[k]:
            k = fail[k - 1]
        if pat[i] == pat[k]:
            k += 1
        fail[i] = k
    starts, k = [], 0
    for i, ch in enumerate(text):
        while k and ch != pat[k]:
            k = fail[k - 1]
        if ch == pat[k]:
            k += 1
        if k == m:
            starts.append(i - m + 1)
            k = fail[k - 1]
    return starts


