def find_winners(matches: list[list[int]]) -> list[list[int]]:
    losses = {}
    for winner, loser in matches:
        losses.setdefault(winner, 0)       # winners must be recorded even if unbeaten
        losses[loser] = losses.get(loser, 0) + 1
    unbeaten = sorted(p for p, c in losses.items() if c == 0)
    one_loss = sorted(p for p, c in losses.items() if c == 1)
    return [unbeaten, one_loss]

