def pancake_sort(arr: list[int]) -> list[int]:
    a = arr[:]
    flips = []
    for size in range(len(a), 1, -1):
        i = a.index(size)
        if i == size - 1:
            continue                   # already in its final position
        if i != 0:
            a[:i + 1] = a[:i + 1][::-1]   # bring `size` to the front
            flips.append(i + 1)
        a[:size] = a[:size][::-1]      # drop it into place at index size - 1
        flips.append(size)
    return flips

