def video_stitching(clips: list[list[int]], time: int) -> int:
    furthest = [0] * time            # furthest[s] = max end of a clip starting at s
    for start, end in clips:
        if start < time:
            furthest[start] = max(furthest[start], end)
    used = 0
    covered = 0                      # [0, covered] is already covered
    best = 0                         # farthest end among clips starting <= t
    for t in range(time):
        best = max(best, furthest[t])
        if t == covered:             # current coverage ends here: need a new clip
            if best <= t:
                return -1
            used += 1
            covered = best
    return used

def is_possible(n: int, edges: list[list[int]]) -> bool:
    degree = [0] * (n + 1)
    neighbours = defaultdict(set)
    for a, b in edges:
        degree[a] += 1
        degree[b] += 1
        neighbours[a].add(b)
        neighbours[b].add(a)
    odd = [v for v in range(1, n + 1) if degree[v] % 2]

    def free(u, v):
        return v not in neighbours[u]

    if not odd:
        return True
    if len(odd) == 2:
        a, b = odd
        if free(a, b):
            return True
        # Route through a third node adjacent to neither endpoint.
        for c in range(1, n + 1):
            if c != a and c != b and free(a, c) and free(b, c):
                return True
        return False
    if len(odd) == 4:
        a, b, c, d = odd
        return ((free(a, b) and free(c, d)) or
                (free(a, c) and free(b, d)) or
                (free(a, d) and free(b, c)))
    return False

