def group_strings(words: list[str]) -> list[int]:
    counts = Counter()
    for w in words:
        mask = 0
        for ch in w:
            mask |= 1 << (ord(ch) - 97)
        counts[mask] += 1

    masks = list(counts)
    index = {m: i for i, m in enumerate(masks)}
    parent = list(range(len(masks)))
    size = [counts[m] for m in masks]

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if size[rx] < size[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        size[rx] += size[ry]

    removed_owner = {}   # mask with one bit removed -> first node that produced it
    for i, m in enumerate(masks):
        for b in range(26):
            bit = 1 << b
            other = index.get(m ^ bit)       # add or delete one letter
            if other is not None:
                union(i, other)
            if m & bit:
                key = m ^ bit                # replacement: same mask after removing a bit
                if key in removed_owner:
                    union(i, removed_owner[key])
                else:
                    removed_owner[key] = i

    groups = 0
    largest = 0
    for i in range(len(masks)):
        if find(i) == i:
            groups += 1
            largest = max(largest, size[i])
    return [groups, largest]

def count_triples(n: int) -> int:
    count = 0
    limit = n * n
    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):      # a == b never works: 2a^2 is not a square
            s = a * a + b * b
            if s > limit:
                break                      # larger b only grows s
            c = math.isqrt(s)
            if c * c == s:
                count += 2                 # (a, b, c) and (b, a, c)
    return count

