def min_time(n: int, edges: list[list[int]], has_apple: list[bool]) -> int:
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    parent = [-1] * n
    parent[0] = 0
    order = [0]
    for v in order:  # BFS: order grows while we iterate
        for w in adj[v]:
            if parent[w] == -1:
                parent[w] = v
                order.append(w)
    needed = list(has_apple)  # does the subtree of v hold an apple?
    seconds = 0
    for v in reversed(order):
        if v != 0 and needed[v]:
            seconds += 2
            needed[parent[v]] = True
    return seconds

def insert_into_bst(root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
    new_node = TreeNode(val)
    if root is None:
        return new_node
    cur = root
    while True:
        if val < cur.val:
            if cur.left is None:
                cur.left = new_node
                return root
            cur = cur.left
        else:
            if cur.right is None:
                cur.right = new_node
                return root
            cur = cur.right

